</style>
</head>
<body>
<canvas id="cv"></canvas>
<div id="hud"></div>
<script>
"use strict";
/* ============================================================
   Bolas a saltar dentro de um nonágono regular em rotação.
   - 9 lados, raio 260 px, 360° em 7 s, sentido horário.
   - 13 bolas (r = 14 px, numeradas 0..12, o número gira com a bola).
   - Física própria (sem bibliotecas): gravidade, arrasto do ar,
     fricção de contacto, restituição 0.82, colisão bola-bola e
     bola-parede (paredes em movimento: a resposta tem em conta a
     velocidade da parede no ponto de impacto).
   - Contrato de verificação: window.__bench.getState() / .step(dt)
   ============================================================ */
(() => {
  const TAU = Math.PI * 2;

  // ---------------- configuração ----------------
  const POLY_N  = 9;                      // lados
  const POLY_R  = 260;                    // raio circunscrito (px)
  const PERIOD  = 7;                      // período de rotação (s)
  const OMEGA   = TAU / PERIOD;           // rad/s (horário no referencial do canvas)
  const APOHEM  = POLY_R * Math.cos(Math.PI / POLY_N); // distância centro->lados
  const BALL_R  = 14;                     // raio das bolas (px)
  const GRAV    = 2000;                   // gravidade (px/s^2, +y para baixo)
  const AIR_K   = 0.10;                   // fricção do ar (arrasto linear, 1/s)
  const REST    = 0.82;                   // restituição (parede e bola-bola)
  const WALL_F  = 0.16;                   // fricção tangencial no contacto com a parede
  const BALL_F  = 0.10;                   // fricção tangencial no contacto bola-bola
  const MAX_H   = 1 / 240;                // subpasso máximo (s) p/ determinismo

  // ---------------- canvas ----------------
  const canvas = document.getElementById("cv");
  const ctx = canvas.getContext("2d");
  const hud = document.getElementById("hud");
  let W = 0, Hh = 0, cx = 0, cy = 0;

  // ---------------- estado da simulação ----------------
  let simT = 0;        // segundos decorridos desde o início
  let autoPaused = false; // passo manual (window.__bench.step) suspende o relógio do rAF
  const balls = [];    // { id, x, y, vx, vy, r, rot, rotV }

  const polyAngle = () => simT * OMEGA;   // orientação atual do polígono (rad)

  // Posição inicial: 1 + 6 + 6 em anéis concêntricos, sem sobrepensões,
  // todas próximas do centro e com velocidade nula.
  function initBalls() {
    const P = (id, x, y) => balls.push({
      id, x, y, vx: 0, vy: 0, r: BALL_R,
      rot: (id * 0.9) % TAU,
      rotV: (((id + 1) * 53) % 11 - 5) * 0.7
    });
    P(0, cx, cy);
    for (let i = 1; i <= 6; i++) {
      const a = i * TAU / 6;
      P(i, cx + Math.cos(a) * 34, cy + Math.sin(a) * 34);
    }
    for (let i = 7; i <= 12; i++) {
      const a = TAU / 12 + (i - 7) * TAU / 6;
      P(i, cx + Math.cos(a) * 68, cy + Math.sin(a) * 68);
    }
  }

  function resize() {
    const dpr = window.devicePixelRatio || 1;
    W = window.innerWidth; Hh = window.innerHeight;
    const nx = W / 2, ny = Hh / 2;
    if (balls.length) {
      const dx = nx - cx, dy = ny - cy;   // acompanha o novo centro
      for (const b of balls) { b.x += dx; b.y += dy; }
    }
    cx = nx; cy = ny;
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(Hh * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  window.addEventListener("resize", resize);
  resize();
  initBalls();

  // ---------------- geometria do polígono ----------------
  function vertexAt(i, a0) {
    const a = a0 + i * TAU / POLY_N;
    return { x: cx + Math.cos(a) * POLY_R, y: cy + Math.sin(a) * POLY_R };
  }

  // Normal unitária orientada para fora do lado i (em função do ângulo atual).
  function nOut(i) {
    const am = polyAngle() + (i + 0.5) * TAU / POLY_N;
    return { x: Math.cos(am), y: Math.sin(am) };
  }

  // Velocidade de um ponto fixo ao polígono (rotação rígida em torno do centro).
  // Para r relativo ao centro: v = OMEGA * (-ry, rx)  ->  rotação horária no ecrã.
  function wallVelAt(px, py) {
    const rx = px - cx, ry = py - cy;
    return { x: -OMEGA * ry, y: OMEGA * rx };
  }

  // A bola está (inteiramente fora?) não — o centro está dentro do polígono?
  function inPoly(px, py) {
    for (let i = 0; i < POLY_N; i++) {
      const n = nOut(i);
      if (n.x * (px - cx) + n.y * (py - cy) > APOHEM + 1e-9) return false;
    }
    return true;
  }

  // Ponto da fronteira do polígono mais próximo de (px, py).
  function closestBoundary(px, py) {
    const a0 = polyAngle();
    let best = null;
    for (let i = 0; i < POLY_N; i++) {
      const A = vertexAt(i, a0), B = vertexAt(i + 1, a0);
      const abx = B.x - A.x, aby = B.y - A.y;
      const denom = abx * abx + aby * aby;
      let t = denom > 0 ? ((px - A.x) * abx + (py - A.y) * aby) / denom : 0;
      if (t < 0) t = 0; else if (t > 1) t = 1;
      const qx = A.x + abx * t, qy = A.y + aby * t;
      const dx = px - qx, dy = py - qy, d2 = dx * dx + dy * dy;
      if (!best || d2 < best.d2) best = { d2, qx, qy, i, t };
    }
    return best;
  }

  // Rede de segurança: se a bola sair do polígono (ex.: subpasso grande),
  // recoloca-a a r dentro, ao longo do raio que passa pelo centro.
  function relocate(b) {
    const px = b.x, py = b.y;
    const dcx = cx - px, dcy = cy - py;
    const dc = Math.hypot(dcx, dcy);
    let best = null;
    for (let i = 0; i < POLY_N; i++) {
      const n = nOut(i);
      const dot = n.x * (px - cx) + n.y * (py - cy);
      if (dot > APOHEM + 1e-9) {
        const den = dcx * n.x + dcy * n.y;             // negativo (raio entra)
        if (den < -1e-9) {
          const f0 = dot - APOHEM;
          const tStar = f0 / (f0 + APOHEM);            // em (0,1)
          if (!best || tStar < best.t) best = { t: tStar };
        }
      }
    }
    let hx, hy;
    if (best) { hx = px + best.t * dcx; hy = py + best.t * dcy; }
    else { hx = cx; hy = cy; }
    const il = dc > 1e-12 ? 1 / dc : 0;
    const nx = dcx * il, ny = dcy * il;                // direção "para dentro" (raio)
    b.x = hx + nx * b.r;
    b.y = hy + ny * b.r;
    const vn = b.vx * nx + b.vy * ny;
    if (vn < 0) { b.vx -= 2 * vn * nx; b.vy -= 2 * vn * ny; }   // refletir para dentro
    b.vx *= 0.9; b.vy *= 0.9;
  }

  // ---------------- resolução de colisões ----------------

  // Bola vs parede (fronteira em movimento): deteta pelo ponto de fronteira
  // mais próximo, separa, aplica restituição com a velocidade relativa à
  // parede no ponto de contacto e fricção tangencial (que também dá spin).
  function resolveWall(b) {
    if (!inPoly(b.x, b.y)) { relocate(b); return; }
    const cb = closestBoundary(b.x, b.y);
    const dx = b.x - cb.qx, dy = b.y - cb.qy;
    const d = Math.sqrt(cb.d2);
    if (d >= b.r) return;                              // sem contacto
    let nx, ny;
    if (d > 1e-9) { nx = dx / d; ny = dy / d; }
    else {                                             // centro na fronteira (degenerate)
      const n = nOut(cb.i); nx = -n.x; ny = -n.y;
    }
    b.x += nx * (b.r - d);                             // separar para dentro
    const w = wallVelAt(cb.qx, cb.qy);                 // velocidade da parede no impacto
    let rvx = b.vx - w.x, rvy = b.vy - w.y;
    const vn = rvx * nx + rvy * ny;
    if (vn < 0) {                                      // em aproximação
      b.vx -= (1 + REST) * vn * nx;                    // restituição 0.82
      b.vy -= (1 + REST) * vn * ny;
    }
    // fricção tangencial de contacto (reduz o deslizamento relativo à parede)
    rvx = b.vx - w.x; rvy = b.vy - w.y;
    const vn2 = rvx * nx + rvy * ny;
    const vtx = rvx - vn2 * nx, vty = rvy - vn2 * ny;
    b.vx -= WALL_F * vtx;
    b.vy -= WALL_F * vty;
    // spin visível: rotação tende para a velocidade de rolagem relativa
    const sT = (b.vx - w.x) * -ny + (b.vy - w.y) * nx;
    b.rotV = b.rotV * 0.65 + (sT / b.r) * 0.35;
  }

  // Bola vs bola: massas iguais, semitruncamento posicional e impulso
  // normal (restituição) + fricção tangencial + troca de spin.
  function resolvePair(a, b) {
    const dx = b.x - a.x, dy = b.y - a.y;
    const minD = a.r + b.r;
    const d2 = dx * dx + dy * dy;
    if (d2 >= minD * minD) return;
    const d = Math.sqrt(d2);
    let nx, ny;
    if (d > 1e-9) { nx = dx / d; ny = dy / d; } else { nx = 1; ny = 0; }
    // separar (metade para cada)
    const push = (minD - d) / 2;
    a.x -= nx * push; a.y -= ny * push;
    b.x += nx * push; b.y += ny * push;
    // impulso normal (restituição)
    let rvx = a.vx - b.vx, rvy = a.vy - b.vy;
    const vn = rvx * nx + rvy * ny;                    // > 0 => em aproximação
    if (vn > 0) {
      const j = (1 + REST) * vn / 2;
      a.vx -= j * nx; a.vy -= j * ny;
      b.vx += j * nx; b.vy += j * ny;
    }
    // fricção tangencial (reduz o deslizamento relativo)
    rvx = a.vx - b.vx; rvy = a.vy - b.vy;
    const vn2 = rvx * nx + rvy * ny;
    const vtx = rvx - vn2 * nx, vty = rvy - vn2 * ny;
    const f = BALL_F / 2;
    a.vx -= f * vtx; a.vy -= f * vty;
    b.vx += f * vtx; b.vy += f * vty;
    // spin (visual): o deslizamento relativo transfere rotação
    const sT = vtx * -ny + vty * nx;
    if (Math.abs(sT) > 1e-9) {
      const sp = (BALL_F * sT) / b.r;
      a.rotV -= sp;
      b.rotV += sp;
    }
    const cap = 30;
    if (a.rotV > cap) a.rotV = cap; else if (a.rotV < -cap) a.rotV = -cap;
    if (b.rotV > cap) b.rotV = cap; else if (b.rotV < -cap) b.rotV = -cap;
  }

  // Passadas finais só de posição: garantem sem exceção
  // "as bolas nunca saem do polígono nem se sobrepõem".
  function hardWall(b) {
    if (!inPoly(b.x, b.y)) { relocate(b); return; }
    const cb = closestBoundary(b.x, b.y);
    const d = Math.sqrt(cb.d2);
    if (d >= b.r) return;
    let nx, ny;
    if (d > 1e-9) { nx = (b.x - cb.qx) / d; ny = (b.y - cb.qy) / d; }
    else { const n = nOut(cb.i); nx = -n.x; ny = -n.y; }
    b.x += nx * (b.r - d);
    b.y += ny * (b.r - d);
  }

  function hardPair(a, b) {
    const dx = b.x - a.x, dy = b.y - a.y;
    const minD = a.r + b.r;
    const d2 = dx * dx + dy * dy;
    if (d2 >= minD * minD) return;
    const d = Math.sqrt(d2);
    const nx = d > 1e-9 ? dx / d : 1;
    const ny = d > 1e-9 ? dy / d : 0;
    const push = (minD - d) / 2;
    a.x -= nx * push; a.y -= ny * push;
    b.x += nx * push; b.y += ny * push;
  }

  function clampSpin(b) {
    if (b.rotV > 30) b.rotV = 30; else if (b.rotV < -30) b.rotV = -30;
    b.rot = ((b.rot % TAU) + TAU) % TAU;
  }

  // ---------------- integração ----------------
  function substep(h) {
    // forças
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      b.vy += GRAV * h;
      const k = AIR_K * h;
      if (k < 1) { const f = 1 - k; b.vx *= f; b.vy *= f; }
      b.rotV *= (1 - 0.03 * h);
      b.x += b.vx * h;
      b.y += b.vy * h;
      b.rot += b.rotV * h;
    }
    // colisões (iterativas)
    for (let it = 0; it < 4; it++) {
      for (let i = 0; i < balls.length; i++) resolveWall(balls[i]);
      for (let i = 0; i < balls.length; i++)
        for (let j = i + 1; j < balls.length; j++)
          resolvePair(balls[i], balls[j]);
    }
    // garantia forte das restrições
    for (let it = 0; it < 6; it++) {
      for (let i = 0; i < balls.length; i++) hardWall(balls[i]);
      for (let i = 0; i < balls.length; i++)
        for (let j = i + 1; j < balls.length; j++)
          hardPair(balls[i], balls[j]);
    }
    for (let i = 0; i < balls.length; i++) clampSpin(balls[i]);
  }

  // Avança exatamente dt segundos, de forma determinística
  // (n subpassos iguais; nenhuma fonte de aleatoriedade).
  function advance(dt) {
    if (!(dt > 0) || !isFinite(dt)) return;
    if (dt > 5) dt = 5;                               // teto de segurança
    const n = Math.max(1, Math.ceil(dt / MAX_H));
    const h = dt / n;
    const t0 = simT;
    for (let k = 1; k <= n; k++) {
      simT = t0 + k * h;
      substep(h);
    }
  }

  // ---------------- renderização ----------------
  function render() {
    ctx.clearRect(0, 0, W, Hh);
    const bg = ctx.createLinearGradient(0, 0, 0, Hh);
    bg.addColorStop(0, "#0d1420");
    bg.addColorStop(1, "#070a10");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, Hh);

    const a0 = polyAngle();
    const verts = [];
    for (let i = 0; i < POLY_N; i++) verts.push(vertexAt(i, a0));

    // polígono
    ctx.beginPath();
    ctx.moveTo(verts[0].x, verts[0].y);
    for (let i = 1; i < POLY_N; i++) ctx.lineTo(verts[i].x, verts[i].y);
    ctx.closePath();
    ctx.fillStyle = "rgba(82, 128, 208, 0.07)";
    ctx.fill();
    ctx.save();
    ctx.strokeStyle = "#5f8dd6";
    ctx.lineWidth = 3;
    ctx.lineJoin = "round";
    ctx.shadowColor = "rgba(95,141,214,0.8)";
    ctx.shadowBlur = 14;
    ctx.stroke();
    ctx.restore();

    // vértices (mostram a rotação)
    ctx.fillStyle = "#9fc1f2";
    for (const v of verts) {
      ctx.beginPath();
      ctx.arc(v.x, v.y, 4, 0, TAU);
      ctx.fill();
    }

    // bolas
    for (const b of balls) {
      const hue = (b.id * 137.508) % 360;
      const g = ctx.createRadialGradient(b.x - b.r * 0.45, b.y - b.r * 0.5, b.r * 0.15, b.x, b.y, b.r);
      g.addColorStop(0, "hsl(" + hue + ",72%,74%)");
      g.addColorStop(1, "hsl(" + hue + ",65%,42%)");
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, TAU);
      ctx.fillStyle = g;
      ctx.fill();
      ctx.lineWidth = 1.5;
      ctx.strokeStyle = "hsl(" + hue + ",60%,25%)";
      ctx.stroke();
      // número por cima da bola, a rodar com o spin
      ctx.save();
      ctx.translate(b.x, b.y);
      ctx.rotate(b.rot);
      ctx.fillStyle = "#ffffff";
      ctx.font = "700 15px ui-monospace, Menlo, Consolas, monospace";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(String(b.id), 0, 1);
      ctx.restore();
    }

    // HUD
    let mode = "auto (requestAnimationFrame)";
    if (autoPaused) mode = "manual (window.__bench.step)";
    hud.textContent =
      "t = " + simT.toFixed(3) + " s   ·   θ = " + (polyAngle() % TAU).toFixed(2) + " rad   ·   " + mode;
  }

  // ---------------- laço de animação ----------------
  let last = performance.now();
  function frame(now) {
    let dt = (now - last) / 1000;
    last = now;
    if (autoPaused || dt < 0) dt = 0;
    if (dt > 1 / 30) dt = 1 / 30;                     // pausa/aba em segundo plano
    if (dt > 0) advance(dt);
    render();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  // ---------------- contrato de verificação ----------------
  window.__bench = {
    getState() {
      return {
        t: simT,
        poly: {
          n: POLY_N,
          radius: POLY_R,
          cx: cx,
          cy: cy,
          angle: simT * OMEGA,
          periodSec: PERIOD
        },
        balls: balls.map(b => ({ id: b.id, x: b.x, y: b.y, r: b.r, vx: b.vx, vy: b.vy }))
      };
    },
    // Avança a simulação excecionalmente dt (s), de forma determinística.
    // Ao ser chamada, suspende o avanço automático via requestAnimationFrame.
    step(dtSeconds) {
      autoPaused = true;
      advance(dtSeconds);
      render();
    },
    // (útil) retoma a animação normal via requestAnimationFrame
    resume() { autoPaused = false; last = performance.now(); }
  };
})();
</script>
</body>
</html>
