function hardWall(b) {
  if (!inPoly(b.x, b.y)) { relocate(b); return; }
  const cb = closestBoundary(b.x, b.y);
  const d = Math.sqrt(cb.d2);
  if (d >= b.r) return;
  let nx, ny;
  if (d > 1e-9) { nx = (b.x - cb.qx) / d; ny = (b.y - cb.qy) / d; }
  else { const n = nOut(cb.i); nx = -n.x; ny = -n.y; }
  b.x += nx * (b.r - d);
  b.y += ny * (b.r - d);
}

